import docx, io, sys
for f in ['UserX.docx','UserX_申请人自述.docx']:
    d = docx.Document(f)
    out = []
    for p in d.paragraphs:
        t = p.text.strip()
        if t: out.append(t)
    for ti, tb in enumerate(d.tables):
        out.append('=== TABLE %d ===' % ti)
        for r in tb.rows:
            cells = [c.text.strip().replace(chr(10),' / ') for c in r.cells]
            out.append(' | '.join(cells))
    open('_extract_'+f.replace('.docx','')+'.txt','w',encoding='utf-8').write('\n'.join(out))
